import hashlib, httpx
from pwdlib import PasswordHash
from pwdlib.exceptions import UnknownHashError

class PasswordCheckUnavailable(Exception):
    """HIBP could not be reached or returned an invalid response."""


async def is_password_compromised(password: str) -> bool:
    # HaveIgetPwned (HIBP) api uses sha1 for lookup table, sha1 is a 160bits hashing algo i.e. 40 hex chars
    # since sha1 works with bytes, encode("utf-8") converts str to bytes, then hash generated by sha1() is converted into hex code by hexdigest and further made uppercase by upper()
    sha1_hash = hashlib.sha1(password.encode("utf-8")).hexdigest().upper()
    prefix, suffix = sha1_hash[:5], sha1_hash[5:] # HIBP uses 1st five hex code as lookup range

    try:
        async with httpx.AsyncClient(timeout=3.0) as client:
            res = await client.get(
                f"https://api.pwnedpasswords.com/range/{prefix}",
                headers={"Add-Padding": "true"},
            )
            res.raise_for_status()
    except httpx.HTTPError as exc:
        raise PasswordCheckUnavailable from exc

    # res.text converts the response body to string.
    # the res of HIBP when coverted to text looks like:
    # 0018A45C4D1DEF81644B54AB7F969B88D65:1
    # 00D4F6E8FA6EECAD2A3AA415EEC418D38EC:2
    # 011053FD0102E94D6AE2F8B83D76FAF94F6:1
    # splitlines() convert whole text into list with each line being an element of list
    for line in res.text.splitlines():
        try:
            returned_suffix, count = line.split(":", maxsplit=1)
            count = int(count) # count is still str so typecast it to int
        except ValueError as exc:
            raise PasswordCheckUnavailable("Invalid HIBP response") from exc
        if returned_suffix.upper() == suffix:
            return count > 0
    return False

password_hash = PasswordHash.recommended() # currently the recommended hashing algo is argon2

def hash_pwd(password: str):
    return password_hash.hash(password=password)

def verify_pwd(plain_pwd, hashed_pwd):
    try:
        return password_hash.verify(plain_pwd, hashed_pwd)
    except UnknownHashError:
        return False